{
  "proposal": {
    "title": "通勤缩短后，临下班的任务会派给谁？到岗团队的派工规则与时间分配",
    "decision": "重构并保留为探索性候选。把晚间研究的焦点从员工个人是否加班，移到通勤缩短后团队是否把原本可由他人接手的任务转派给更容易留下的人。午间回家保留为对照，用来检验可达性和实际离岗权如何共同影响活动选择。两条变化可以并存，学术增量取决于能否检验晚间的任务转派。",
    "event_basis": [
      {
        "event": "E1",
        "observation": "帖主回忆，第一份工作时由地铁通勤改为步行。后来换工作后曾住在距单位步行约五分钟处，午间可以回家做饭、午睡。她把下班后时间较多同时归于住得近和很少加班。最清楚的午间经历与换工作相伴，无法从这段叙述中分离住房和岗位变化。",
        "locator": "S1 原帖第43至46行",
        "url": "https://www.douban.com/group/topic/317404855/?_spm_id=MTk1MTEwMjcz"
      },
      {
        "event": "E2",
        "observation": "另一位受访者回忆，就近居住时容易在办公室多待，和附近同事的日常交往也较多。后来购房搬远时，预算、居住环境和工作生活边界均进入其解释。久留期间是否工作、谁发起任务、是否替代同事完成任务以及能否推迟，均未知。",
        "locator": "S2 第102至114行，久留和同事交往见第113至114行",
        "url": "https://ftp.laborinfocn.com/articles/76670"
      },
      {
        "event": "背景调查",
        "observation": "商业调查中，78%的受访者把通勤时间符合预期列为租房优先考虑因素。该比例只描述调查样本内的住房偏好。",
        "locator": "S3 网页提取版第692至705行",
        "url": "https://reportify-1252068037.cos.ap-beijing.myqcloud.com/media/production/s_c1f2a4c3_c1f2a4c399a9bcd2520d4c6a35e75726.pdf"
      }
    ],
    "conceptualization": "分别观察门到门通勤、离岗后的时间余量、实际工作以及员工对临时任务的处置权。晚间余量以请求发生前记录的预计返程时间和原定到家时间或下一项义务估算，同时记录员工何时原本打算离岗、派工者当时掌握哪些信息、任务能否推迟、谁有资格接手及推迟后的实际后果。午间净可用时间由休息窗口减去往返、进出和必要缓冲得到，活动所需的连续时间在观察结果前确定。办公室停留、同事社交和实际工作分别记录，午间额外往返计入全天出行。",
    "theoreticalization": {
      "evening": "在任务可以由多名合资格员工接手的团队里，通勤缩短可能降低一名员工晚走的代价。如果主管能观察到其可用性，并有权按可用性派工，临下班的任务可能向该员工集中。若任务总量基本稳定且确有转派，通勤未变的可替代同事承担这类任务的份额也应下降。预先锁定的轮值或按岗位固定的派工应削弱这种变化。只有可核对的拒绝、推迟及其后果，才能进一步判断员工是否受到组织约束。",
      "midday": "午休只在净可用时间足以完成活动时提供机会。在活动意愿和净可用时间相近、且活动已具备时间可行性的员工中，比较实际可自由离岗与须值守的情况。若回家主要随门到门往返时间改变，且离岗规则相近，时间地理的可达性解释已足以解释该结果。",
      "abstract_relation": "个人因出行阻力下降而得到的时间余量，可以通过按可用性派工影响同事的工作分配。这个跨人影响取决于组织能否识别员工的可用性、能否更换承接者，以及派工权是否受轮值约束。"
    },
    "context_transfer": "比较两种稳定到岗情境。一种是搬近单位，另一种是住所、岗位和团队不变，但既有交通改善缩短晚间返程。若派工者同样能够观察到员工的可用性，且任务与分派规则可比，两种情境都应有机会出现任务集中和同事间替代。若交通改善只影响早晚，午间往返条件保持稳定，午间回家没有相同预测。若晚间变化只出现在搬家组，优先核对附近同事网络、住房条件和新形成的居住安排。这项比较检验机制的适用条件。",
    "literature_dialogue": [
      {
        "dimension": "研究对象与议题",
        "finding_and_response": "Aksoy 等用覆盖27个国家的调查研究居家办公节省的通勤时间。按调查回答，样本平均约40%的节省时间用于主要或第二份工作。结合上一轮围绕 Wang 等的通勤与劳动供给研究，工作可以吸收通勤节省已是明确的近邻问题。本候选把研究对象推进到同一批到岗团队的待派任务与可能承接这些任务的同事，追问任务来自哪里以及谁因此少做了这类工作。",
        "locator": "NBER 工作论文摘要、§I、§II，第30至32、83、105至109行附近",
        "url": "https://www.nber.org/system/files/working_papers/w30866/w30866.pdf"
      },
      {
        "dimension": "活动可达性理论",
        "finding_and_response": "现代时间地理框架已明确讨论个体能力、活动协调和制度规则如何共同限制可达性。午休够往返、单位又允许离岗，落在该框架已有的解释范围内。因此午间用于验证活动条件和校准记录，晚间才检验个人时间余量如何通过组织规则改变其他人的任务分配。",
        "locator": "正文第108至111行及后续约束框架",
        "url": "https://link.springer.com/article/10.1007/s10109-023-00404-1"
      },
      {
        "dimension": "工作强化与边界理论",
        "finding_and_response": "Kelliher 与 Anderson 已区分工作强化的外加要求、机会促成和互惠交换三种来源。上一轮关于 Elfering 等、Jachimowicz 等和 Kelly 等的文献概述，也分别提出自主性、角色转换和组织安排等近邻解释。本候选将员工自愿多做、工作与家庭角色转换、主管转派任务落实到不同的时间顺序和可观察结果。",
        "locator": "出版社摘要第31至32行",
        "url": "https://journals.sagepub.com/doi/abs/10.1177/0018726709349199"
      },
      {
        "dimension": "任务分配",
        "finding_and_response": "Kwasnitschka 等的工厂现场研究已经考察按可用性和技能匹配任务，以及从系统分派改为员工选任务后的行为变化。按可用性分工已有实证先例。这里仍值得核查的命题是，工作场所以外的出行变化能否经由既有派工规则，改变临下班任务在员工之间的归属。",
        "locator": "引言第36至49行，任务系统说明第109行附近",
        "url": "https://journals.sagepub.com/doi/full/10.1177/10591478251400469"
      }
    ],
    "observations_that_changed_the_judgment": [
      "时间地理文献已把可达性与制度规则放在同一框架内。反方又指出，等量的早晚通勤节省可以对应完全不同的午间往返条件。午间门槛因而退回为对照，日内分段也退出创新主张。",
      "跨国调查已经观察到部分通勤节省流向工作，工作强化研究也已给出员工主动增做和组织要求等解释。反方的例行请求反例说明，员工主动接下可推迟的工作，就能同时出现午间自主活动增加、晚间多工作和按原计划到家。这组现象不足以判定谁在支配时间。",
      "反方指出，员工可以先决定留下，主管随后才向在场的人派工。工厂研究又说明按可用性派工本身已有先例。主检验因此改看变化前存在的派工规则、完整的任务流入与候选承接者，以及通勤未变同事的任务份额。E2 缺少这些观察，所以它仍只提供问题线索。"
    ],
    "competing_explanations": [
      {
        "explanation": "主动留下、主动揽活或同事社交",
        "discriminating_evidence": "在请求发出前记录离岗计划，区分员工主动揽活、被指派和自愿社交。若晚间增量主要来自预先计划的在场、自选任务或社交，且未观察到任务从其他候选人转来，应缩小派工解释。"
      },
      {
        "explanation": "任务高峰、排班变化或任务从别的时段移入",
        "discriminating_evidence": "记录全部符合研究口径的任务，包括延后、无人接手或转交他人的任务。核对任务到达量、紧急程度、预先排班、同事资格和当天、次日及居家工作。若工作增加随团队任务流入同步变化，优先考虑需求增长。若全天或次日工作相应减少，报告时段转移。"
      },
      {
        "explanation": "住房选择、同事网络、家庭义务或心理过渡",
        "discriminating_evidence": "事前记录住房备选、固定照护时段、同事居住关系、沿途活动和角色转换体验。用住所稳定的通勤变化作比较。若变化集中在体验或社交，而请求、接受和承接者的记录保持稳定，优先采用对应解释。"
      }
    ]
  },
  "evidence_urls": [
    "https://www.nber.org/system/files/working_papers/w30866/w30866.pdf",
    "https://link.springer.com/article/10.1007/s10109-023-00404-1",
    "https://journals.sagepub.com/doi/abs/10.1177/0018726709349199",
    "https://journals.sagepub.com/doi/full/10.1177/10591478251400469"
  ],
  "academic_increment": {
    "claim": "待验证的增量是通勤改善对同事任务分配的影响。在任务可替代、到达量相近的条件下，原有的按可用性派工规则可能使任务向返程余量增加的员工集中，并使通勤未变的可替代同事少承担同类任务。这个命题对团队内谁获派、谁少承担以及何时出现变化给出了联合预测。即使团队总工时保持稳定，也可以检验这种重新分配。",
    "test_and_falsification": "事前界定下班前观察窗口、任务口径、候选承接资格、规则类型和主要结果。以全部符合口径的任务为分母，检验通勤变化员工与可替代同事的承接份额是否反向变化，以及该变化是否集中在既有的按可用性派工情境。若只看到某人晚走、个人主动做更多、任务总量上升，或固定轮值中也出现相近的转移，派工命题缺乏支持。若观察到转派但请求可以无后果地推迟，可报告任务重新分配，组织约束仍需另证。",
    "status": "新意和机制均待验证。本轮打开的研究分别覆盖时间用途、活动可达性、工作强化和按可用性派工。是否已有研究直接检验通勤变化引起的同事间任务替代，未知。"
  },
  "feasibility": {
    "current": "两起独立事件足以确定访谈问题和记录口径。正式检验需要团队层面的任务流入与派工记录，个人日记或考勤只能支持较窄的活动与留岗研究。",
    "pilot": "在同城到岗团队做前瞻试测，优先寻找已有稳定派工规则、能提供去标识任务记录、且员工通勤即将变化的团队。同步记录同团队通勤未变且有资格接手同类任务的员工。变化前后各两个完整工作周可作为流程试测窗口，正式观察期由任务频次、记录缺失和团队覆盖决定。用既有轮值、排班或派工记录核实规则，用短日记记录请求前的离岗计划与返程余量，用任务记录核对发起、候选人、指派、推迟、重派和实际完成。分析时将同事视为可能受转派影响的观察对象。若需估计团队层面的对照变化，另找未受该团队派工影响的可比团队。",
    "go_no_go": "能覆盖完整任务流入、合理重建候选承接者，并观察到可比的事前规则差异或可信的既有规则变化，才推进正式检验。搬家比较首先用于估计关联和核对过程，因果判断需要可信的外生通勤变化及对同期组织变化的核查。若试测只能取得个人自述和在场时长，停止以同事间任务替代为核心的研究设计，将结论限于活动用途与留岗体验。",
    "unknowns": "合适团队、交通变化事件、任务频次、规则差异、员工和组织的记录授权、拒绝或推迟事件的可核验程度，以及现成数据能否覆盖完整任务流入，均未知。"
  },
  "limitations": [
    "沿用初始事件包的定位与证据边界。两案来自不同叙述者和来源，各自仍主要依靠单方回顾。E1 同时涉及换工作，E2 同时涉及购房、预算和居住偏好。两案均缺少独立行为记录，实际时间增减、机制方向和发生率未知。",
    "新增证据用于判断理论重合与研究缺口，未提供 E1 或 E2 的独立印证，也未确认一处可直接实施情境转换的交通事件。上一轮文献仅按给出的历史概述使用。",
    "本轮共使用12个原生联网动作，包括6条查询和6次打开。两次打开失败，证据数组逐条列出其余4个成功打开且用于论证的新页面。"
  ]
}
